/** `url("data:image/svg+xml,…")` for an NDS icon, for mask-image. */
export function iconUrl(name) {
    return `url("data:image/svg+xml,${encodeURIComponent(SVG[name])}")`;
}
/** The style that draws an NDS icon as a mask in the current text colour. */
export function iconMask(name) {
    const value = `${iconUrl(name)} center / contain no-repeat`;
    return { mask: value, WebkitMask: value };
}
